// /frontend-react/src/components/MedicineReminder.js

import React, { useState, useEffect } from 'react';
import HeaderBar from './HeaderBar';

// --- LOCAL MOCK DATA ---
const mockMedicineData = {
    // Current dose reminder
    medicineName: "Blood Pressure Pill",
    dosage: "5mg",
    frequency: "Once Daily (Morning)",
    lastTaken: "2025-12-05 08:00 AM", // Used for the next reminder logic
    
    // Refill warning logic
    pillsRemaining: 10,
    isRefillLow: true, // Set to true to trigger the low warning logic for demo
    refillDate: "2025-12-12",
    
    // Mock Courier Info (if delivery is chosen)
    courier: {
        name: "Alex C.",
        deliveryVehicle: "Bike Courier",
        eta: "3 hours",
    }
};

function MedicineReminder({ isEasyMode, goToPage }) {
    const [isDeliveryConfirmed, setIsDeliveryConfirmed] = useState(false);
    const [isDeliveryNeeded, setIsDeliveryNeeded] = useState(null); // true/false for refill prompt

    const medicine = mockMedicineData;

    // --- Daily Reminder Logic ---
    const handleTaken = () => {
        console.log("Medicine Taken confirmed!");
        // In a real app: Update the lastTaken timestamp and schedule the next reminder.
        alert(`Confirmed! Next pill due tomorrow morning.`);
    };

    // --- Refill Logic Handlers ---
    const handleRefillDecision = (needed) => {
        setIsDeliveryNeeded(needed);
        if (needed) {
            // Simulate sending data to backend (mock confirmation)
            setTimeout(() => {
                setIsDeliveryConfirmed(true);
                console.log("Delivery booked, showing courier status.");
            }, 500);
        } else {
            console.log("Delivery declined. Setting daily reminders to get medicine.");
            // Logic to set persistent reminders...
        }
    };

    // Style for the main daily reminder button (Time to take now)
    const reminderButtonStyle = {
        padding: '25px',
        backgroundColor: '#4CAF50', // Green for Go/Action
        color: 'white',
        fontSize: isEasyMode ? '36px' : '24px',
        fontWeight: 'bold',
        borderRadius: '15px',
        border: 'none',
        cursor: 'pointer',
        boxShadow: '0 5px 15px rgba(0, 70, 0, 0.4)',
        animation: 'pulse-take 1.5s infinite',
    };

    const actionButtonStyle = {
        padding: '15px 30px',
        fontSize: isEasyMode ? '28px' : '18px',
        borderRadius: '8px',
        border: 'none',
        fontWeight: 'bold',
        cursor: 'pointer',
        margin: '10px',
    };

    return (
        <div style={{ padding: '0 20px 20px 20px', textAlign: 'center' }}>
            <HeaderBar title="Medicine" onBackClick={() => goToPage('medical-dashboard')} isEasyMode={isEasyMode} />

            <h2 style={{ fontSize: isEasyMode ? '40px' : '30px', margin: '20px 0 10px 0', color: '#1A73E8' }}>
                Daily Reminder
            </h2>

            {/* 1. Daily Reminder Action */}
            <button 
                onClick={handleTaken}
                style={reminderButtonStyle}
            >
                <span role="img" aria-label="Pill" style={{fontSize: isEasyMode ? '60px' : '40px', display: 'block', marginBottom: '5px'}}>💊</span>
                TAKE YOUR PILL NOW
            </button>

            <p style={{ fontSize: isEasyMode ? '24px' : '16px', color: '#555', marginTop: '15px' }}>
                {medicine.medicineName} ({medicine.dosage})
            </p>

            {/* 2. Refill Warning Section */}
            {medicine.isRefillLow && !isDeliveryConfirmed && (
                <div style={{
                    marginTop: '30px',
                    padding: '20px',
                    border: '3px solid red',
                    borderRadius: '15px',
                    backgroundColor: '#FFEEEE',
                    animation: 'alert-pulse 1s infinite'
                }}>
                    <h3 style={{ fontSize: isEasyMode ? '36px' : '24px', margin: '0 0 15px 0', color: 'red' }}>
                        🔴 MEDICINE LOW! 🔴
                    </h3>
                    <p style={{ fontSize: isEasyMode ? '24px' : '18px', margin: '10px 0' }}>
                        Running out in {medicine.pillsRemaining} days.
                    </p>

                    {/* Refill Decision Prompt */}
                    {isDeliveryNeeded === null ? (
                        <div>
                            <p style={{ fontSize: isEasyMode ? '28px' : '20px', fontWeight: 'bold' }}>
                                Need delivery to your house?
                            </p>
                            <button 
                                onClick={() => handleRefillDecision(true)} 
                                style={{...actionButtonStyle, backgroundColor: 'blue', color: 'white'}}
                            >
                                YES, DELIVER 🚚
                            </button>
                            <button 
                                onClick={() => handleRefillDecision(false)} 
                                style={{...actionButtonStyle, backgroundColor: '#ccc'}}
                            >
                                NO, I'LL GET IT 🚶
                            </button>
                        </div>
                    ) : (
                        // Confirmation Message for No Delivery
                        !isDeliveryNeeded && (
                            <p style={{ fontSize: isEasyMode ? '24px' : '16px', color: 'darkred', fontWeight: 'bold' }}>
                                Okay, we will remind you daily to pick up your refill!
                            </p>
                        )
                    )}
                </div>
            )}

            {/* 3. Delivery Confirmation Status */}
            {isDeliveryConfirmed && (
                 <div style={{
                    marginTop: '30px',
                    padding: '20px',
                    border: '3px solid green',
                    borderRadius: '15px',
                    backgroundColor: '#E6FBE6',
                }}>
                    <h3 style={{ fontSize: isEasyMode ? '36px' : '24px', margin: '0 0 15px 0', color: 'green' }}>
                        ✅ Delivery Confirmed!
                    </h3>
                    <p style={{ fontSize: isEasyMode ? '24px' : '18px', margin: '5px 0' }}>
                        Courier: **{medicine.courier.name}**
                    </p>
                    <p style={{ fontSize: isEasyMode ? '24px' : '18px', margin: '5px 0' }}>
                        ETA: **{medicine.courier.eta}**
                    </p>
                    <span role="img" style={{fontSize: isEasyMode ? '50px' : '30px'}}>📦</span>
                </div>
            )}

            {/* CSS Keyframes */}
            <style jsx>{`
                @keyframes pulse-take {
                    0% { box-shadow: 0 0 10px green; }
                    50% { box-shadow: 0 0 20px limegreen; }
                    100% { box-shadow: 0 0 10px green; }
                }
                @keyframes alert-pulse {
                    0% { transform: scale(1); }
                    50% { transform: scale(1.01); }
                    100% { transform: scale(1); }
                }
            `}</style>
        </div>
    );
}

export default MedicineReminder;
